import os,re
root='.'
hits=[]
for dp,dn,fn in os.walk(root):
 for f in fn:
  p=os.path.join(dp,f)
  try:
   s=open(p,encoding='utf-8',errors='ignore').read()
  except: continue
  if re.search(r'botan',s,re.I) and re.search(r'student',s,re.I) and re.search(r'(specimen|excursion|field trip|collect)',s,re.I):
   hits.append((p,len(s)))
for p,n in hits:
 print(n,p)
print(len(hits))
